WITH [metric_0001, metric_0002, metric_0003, metric_0004, metric_0005, metric_0006, metric_0007, metric_0008, metric_0009, metric_0010, metric_0011, metric_0012, metric_0013, metric_0014, metric_0015, metric_0016, metric_0017, metric_0018, metric_0019, metric_0020, metric_0021, metric_0022, metric_0023, metric_0024, metric_0025, metric_0026, metric_0027, metric_0028, metric_0029, metric_0030, metric_0031, metric_0032, metric_0033, metric_0034, metric_0035, metric_0036, metric_0037, metric_0038, metric_0039, metric_0040, metric_0041, metric_0042, metric_0043, metric_0044, metric_0045, metric_0046, metric_0047, metric_0048, metric_0049, metric_0050, metric_0051, metric_0052, metric_0053, metric_0054, metric_0055, metric_0056, metric_0057, metric_0058, metric_0059, metric_0060, metric_0061, metric_0062, metric_0063, metric_0064, metric_0065, metric_0066, metric_0067, metric_0068, metric_0069, metric_0070, metric_0071, metric_0072, metric_0073, metric_0074, metric_0075, metric_0076, metric_0077, metric_0078, metric_0079, metric_0080, metric_0081, metric_0082, metric_0083, metric_0084, metric_0085, metric_0086, metric_0087, metric_0088, metric_0089, metric_0090, metric_0091, metric_0092, metric_0093, metric_0094, metric_0095, metric_0096, metric_0097, metric_0098, metric_0099, metric_0100] AS measurements
SELECT SUM(arrayCount(x -> isNotNull(x), measurements)) AS cnt,
